<span class="line"><span class="token keyword">const</span> meanAyanamsa <span class="token operator">=</span> eph<span class="token punctuation">.</span><span class="token function">ayanamsa</span><span class="token punctuation">(</span><span class="token string">&#39;lahiri&#39;</span><span class="token punctuation">,</span> when<span class="token punctuation">,</span> <span class="token string">&#39;mean&#39;</span><span class="token punctuation">)</span></span>
