<span class="line">eph<span class="token double-colon punctuation">::</span>JulianDay jd <span class="token operator">=</span> eph<span class="token double-colon punctuation">::</span><span class="token function">julianDayUt</span><span class="token punctuation">(</span><span class="token number">2000</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">12.0</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
